                    BRANCH_HISTORY_SYSTEM_ORIGINS_SCHEMA &&
                    getDurableSystemMessageProvenance(
                      decodeVerifiedPersistedMessage(message),
                    ))),
        );
        state.contexts += 1;
        state.pending = null;
        return { kind: "origin", message, origin };
      }
      invalid();
    },
    finish() {
      if (active) invalid();
